    !---------------------------------------------
    ! rocblas_sgemv
    !---------------------------------------------
    !> \brief  BLAS Level 2 API
    !>
    !> \details
    !> The gemv functions perform one of the matrix-vector operations:
    !>
    !> y := alpha*A*x    + beta*y,   or
    !> y := alpha*A**T*x + beta*y,   or
    !> y := alpha*A**H*x + beta*y,
    !>
    !> where ``alpha`` and ``beta`` are scalars, ``x`` and ``y`` are vectors, and ``A`` is an
    !> ``m`` by ``n`` matrix.
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocBLAS library context queue.
    !> @param[in]
    !> trans     [rocblas_operation]
    !> indicates whether matrix A is tranposed (conjugated) or not.
    !> @param[in]
    !> m         [rocblas_int]
    !> number of rows of matrix A.
    !> @param[in]
    !> n         [rocblas_int]
    !> number of columns of matrix A.
    !> @param[in]
    !> alpha     device pointer or host pointer to scalar alpha.
    !> @param[in]
    !> A         device pointer storing matrix A.
    !> @param[in]
    !> lda       [rocblas_int]
    !> specifies the leading dimension of A.
    !> @param[in]
    !> x         device pointer storing vector x.
    !> @param[in]
    !> incx      [rocblas_int]
    !> specifies the increment for the elements of x.
    !> @param[in]
    !> beta      device pointer or host pointer to scalar beta.
    !> @param[in, out]
    !> y         device pointer storing vector y.
    !> @param[in]
    !> incy      [rocblas_int]
    !> specifies the increment for the elements of y.
    function rocblas_sgemv(handle, trans, m, n, alpha, A, lda, x, incx, beta, y, incy) &
       result(sgemv) &
       bind(C, name="rocblas_sgemv")
       import :: c_ptr, c_int, c_float
       type(c_ptr), value :: handle
       integer(c_int), value :: trans
       integer(c_int), value :: m
       integer(c_int), value :: n
       real(c_float) :: alpha(*)
       real(c_float) :: A(*)
       integer(c_int), value :: lda
       real(c_float) :: x(*)
       integer(c_int), value :: incx
       real(c_float) :: beta(*)
       real(c_float) :: y(*)
       integer(c_int), value :: incy
       integer(c_int) :: sgemv
    end function rocblas_sgemv

    !---------------------------------------------
    ! rocblas_dgemv
    !---------------------------------------------
    function rocblas_dgemv(handle, trans, m, n, alpha, A, lda, x, incx, beta, y, incy) &
       result(dgemv) &
