       integer(c_int), value :: uplo
       integer(c_int), value :: n
       real(c_float) :: alpha(*)
       type(c_ptr), value :: x
       integer(c_int), value :: incx
       type(c_ptr), value :: AP
       integer(c_int), value :: batch_count
       integer(c_int) :: sspr_batched
    end function rocblas_sspr_batched

