    !---------------------------------------------
    ! rocblas_sgeam
    !---------------------------------------------
    !> \brief  BLAS Level 3 API
    !>
    !> \details
    !> The geam functions perform one of the matrix-matrix operations:
    !>
    !> C = alpha*op( A ) + beta*op( B ),
    !>
    !> where ``op( X )`` is one of:
    !>
    !> op( X ) = X      or
    !> op( X ) = X**T   or
    !> op( X ) = X**H,
    !>
    !> ``alpha`` and ``beta`` are scalars, and ``A``, ``B`` and ``C`` are matrices, with
    !> ``op( A )`` an ``m`` by ``n`` matrix, ``op( B )`` an ``m`` by ``n`` matrix, and ``C`` an
    !> ``m`` by ``n`` matrix.
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocBLAS library context queue.
    !> @param[in]
    !> transA    [rocblas_operation]
    !> specifies the form of op( A ).
    !> @param[in]
    !> transB    [rocblas_operation]
    !> specifies the form of op( B ).
    !> @param[in]
    !> m         [rocblas_int]
    !> matrix dimension m.
    !> @param[in]
    !> n         [rocblas_int]
    !> matrix dimension n.
    !> @param[in]
    !> alpha     device pointer or host pointer specifying the scalar alpha.
    !> @param[in]
    !> A         device pointer storing matrix A.
    !> @param[in]
    !> lda       [rocblas_int]
    !> specifies the leading dimension of A.
    !> @param[in]
    !> beta      device pointer or host pointer specifying the scalar beta.
    !> @param[in]
    !> B         device pointer storing matrix B.
    !> @param[in]
    !> ldb       [rocblas_int]
    !> specifies the leading dimension of B.
    !> @param[in, out]
    !> C         device pointer storing matrix C.
    !> @param[in]
    !> ldc       [rocblas_int]
    !> specifies the leading dimension of C.
    function rocblas_sgeam(handle, transA, transB, m, n, alpha, A, lda, beta, B, ldb, C, ldc) &
       result(sgeam) &
       bind(C, name="rocblas_sgeam")
       import :: c_ptr, c_int, c_float
       type(c_ptr), value :: handle
       integer(c_int), value :: transA
       integer(c_int), value :: transB
       integer(c_int), value :: m
       integer(c_int), value :: n
       real(c_float) :: alpha(*)
       real(c_float) :: A(*)
       integer(c_int), value :: lda
       real(c_float) :: beta(*)
       real(c_float) :: B(*)
       integer(c_int), value :: ldb
       real(c_float) :: C(*)
       integer(c_int), value :: ldc
       integer(c_int) :: sgeam
    end function rocblas_sgeam

