    !---------------------------------------------
    ! rocblas_scal_ex
    !---------------------------------------------
    !> \brief  BLAS EX API
    !>
    !> \details
    !> scal_ex  scales each element of vector x with scalar alpha.
    !>
    !> x := alpha * x
    !>
    !> Currently supported datatypes are as follows:
    !>
    !> ----------------------------------------
    !> | alpha_type | x_type | execution_type |
    !> |------------|--------|----------------|
    !> |  f32_r     | bf16_r |     f32_r      |
    !> |  bf16_r    | bf16_r |     f32_r      |
    !> |  f16_r     | f16_r  |     f16_r      |
    !> |  f16_r     | f16_r  |     f32_r      |
    !> |  f32_r     | f16_r  |     f32_r      |
    !> |  f32_r     | f32_r  |     f32_r      |
    !> |  f64_r     | f64_r  |     f64_r      |
    !> |  f32_c     | f32_c  |     f32_c      |
    !> |  f64_c     | f64_c  |     f64_c      |
    !> |  f32_r     | f32_c  |     f32_c      |
    !> |  f64_r     | f64_c  |     f64_c      |
    !> ----------------------------------------
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocblas library context queue.
    !> @param[in]
    !> n         [rocblas_int]
    !> the number of elements in x.
    !> @param[in]
    !> alpha     device pointer or host pointer for the scalar alpha.
    !> @param[in]
    !> alpha_type [rocblas_datatype]
    !> specifies the datatype of alpha.
    !> @param[in, out]
    !> x         device pointer storing vector x.
    !> @param[in]
    !> x_type [rocblas_datatype]
    !> specifies the datatype of vector x.
    !> @param[in]
    !> incx      [rocblas_int]
    !> specifies the increment for the elements of x.
    !> @param[in]
    !> execution_type [rocblas_datatype]
    !> specifies the datatype of computation.
    function rocblas_scal_ex(handle, n, alpha, alpha_type, x, x_type, incx, execution_type) &
       result(scal_ex) &
       bind(C, name="rocblas_scal_ex")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: n
       type(c_ptr), value :: alpha
       integer(c_int), value :: alpha_type
       type(c_ptr), value :: x
       integer(c_int), value :: x_type
       integer(c_int), value :: incx
       integer(c_int), value :: execution_type
       integer(c_int) :: scal_ex
    end function rocblas_scal_ex

