    !---------------------------------------------
    ! rocblas_scal_batched_ex
    !---------------------------------------------
    !> \brief  BLAS EX API
    !>
    !> \details
    !> scal_batched_ex  scales each element of each vector x_i with scalar alpha.
    !>
    !> x_i := alpha * x_i
    !>
    !> Currently supported datatypes are as follows:
    !>
    !> ----------------------------------------
    !> | alpha_type | x_type | execution_type |
    !> |------------|--------|----------------|
    !> |  f32_r     | bf16_r |     f32_r      |
    !> |  bf16_r    | bf16_r |     f32_r      |
    !> |  f16_r     | f16_r  |     f16_r      |
    !> |  f16_r     | f16_r  |     f32_r      |
    !> |  f32_r     | f16_r  |     f32_r      |
    !> |  f32_r     | f32_r  |     f32_r      |
    !> |  f64_r     | f64_r  |     f64_r      |
    !> |  f32_c     | f32_c  |     f32_c      |
    !> |  f64_c     | f64_c  |     f64_c      |
    !> |  f32_r     | f32_c  |     f32_c      |
    !> |  f64_r     | f64_c  |     f64_c      |
    !> ----------------------------------------
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocblas library context queue.
    !> @param[in]
    !> n         [rocblas_int]
    !> the number of elements in x.
    !> @param[in]
    !> alpha     device pointer or host pointer for the scalar alpha.
    !> @param[in]
    !> alpha_type [rocblas_datatype]
    !> specifies the datatype of alpha.
    !> @param[in, out]
    !> x         device array of device pointers storing each vector x_i.
    !> @param[in]
    !> x_type [rocblas_datatype]
    !> specifies the datatype of each vector x_i.
    !> @param[in]
    !> incx      [rocblas_int]
    !> specifies the increment for the elements of each x_i.
    !> @param[in]
    !> batch_count [rocblas_int]
    !> number of instances in the batch.
    !> @param[in]
    !> execution_type [rocblas_datatype]
    !> specifies the datatype of computation.
    function rocblas_scal_batched_ex(handle, n, alpha, alpha_type, x, x_type, incx, batch_count, &
                                     execution_type) &
       result(scal_batched_ex) &
       bind(C, name="rocblas_scal_batched_ex")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       integer(c_int), value :: n
       type(c_ptr), value :: alpha
       integer(c_int), value :: alpha_type
       type(c_ptr), value :: x
       integer(c_int), value :: x_type
       integer(c_int), value :: incx
       integer(c_int), value :: batch_count
       integer(c_int), value :: execution_type
       integer(c_int) :: scal_batched_ex
    end function rocblas_scal_batched_ex

