    !---------------------------------------------
    ! rocblas_scal_strided_batched_ex
    !---------------------------------------------
    !> \brief  BLAS EX API
    !>
    !> \details
    !> The scal_strided_batched_ex functions scale each element of vector ``x`` with scalar
    !> ``alpha`` over a set
    !> of strided batched vectors.
    !>
    !> x := alpha * x
    !>
    !> Currently supported datatypes are as follows:
    !>
    !> ----------------------------------------
    !> | alpha_type | x_type | execution_type |
    !> |------------|--------|----------------|
    !> |  f32_r     | bf16_r |     f32_r      |
    !> |  bf16_r    | bf16_r |     f32_r      |
    !> |  f16_r     | f16_r  |     f16_r      |
    !> |  f16_r     | f16_r  |     f32_r      |
    !> |  f32_r     | f16_r  |     f32_r      |
    !> |  f32_r     | f32_r  |     f32_r      |
    !> |  f64_r     | f64_r  |     f64_r      |
    !> |  f32_c     | f32_c  |     f32_c      |
    !> |  f64_c     | f64_c  |     f64_c      |
    !> |  f32_r     | f32_c  |     f32_c      |
    !> |  f64_r     | f64_c  |     f64_c      |
    !> ----------------------------------------
    !>
    !> @param[in]
    !> handle    [rocblas_handle]
    !> handle to the rocBLAS library context queue.
    !> @param[in]
    !> n         [rocblas_int]
    !> the number of elements in x.
    !> @param[in]
    !> alpha     device pointer or host pointer for the scalar alpha.
    !> @param[in]
    !> alpha_type [rocblas_datatype]
    !> specifies the datatype of alpha.
    !> @param[in, out]
    !> x         device pointer to the first vector x_1.
    !> @param[in]
    !> x_type [rocblas_datatype]
    !> specifies the datatype of each vector x_i.
    !> @param[in]
    !> incx      [rocblas_int]
    !> specifies the increment for the elements of each x_i.
    !> @param[in]
    !> stridex   [rocblas_stride]
    !> stride from the start of one vector (x_i) to the next one (x_i+1).
    !> There are no restrictions placed on stridex. However, ensure that stridex is of an
    !> appropriate size. For a typical
    !> case, this means stridex >= n * incx.
    !> @param[in]
    !> batch_count [rocblas_int]
    !> number of instances in the batch.
    !> @param[in]
    !> execution_type [rocblas_datatype]
    !> specifies the datatype of computation.
    function rocblas_scal_strided_batched_ex(handle, n, alpha, alpha_type, x, x_type, incx, &
                                             stridex, batch_count, execution_type) &
       result(scal_strided_batched_ex) &
       bind(C, name="rocblas_scal_strided_batched_ex")
       import :: c_ptr, c_int, c_long
       type(c_ptr), value :: handle
       integer(c_int), value :: n
       type(c_ptr), value :: alpha
       integer(c_int), value :: alpha_type
       type(c_ptr), value :: x
       integer(c_int), value :: x_type
       integer(c_int), value :: incx
       integer(c_long), value :: stridex
       integer(c_int), value :: batch_count
       integer(c_int), value :: execution_type
       integer(c_int) :: scal_strided_batched_ex
    end function rocblas_scal_strided_batched_ex

    !---------------------------------------------
    ! rocblas_scal_strided_batched_ex_64
    !---------------------------------------------
    function rocblas_scal_strided_batched_ex_64(handle, n, alpha, alpha_type, x, x_type, incx, &
                                                stridex, batch_count, execution_type) &
       result(scal_strided_batched_ex_64) &
       bind(C, name="rocblas_scal_strided_batched_ex_64")
       import :: c_ptr, c_long, c_int
