    !---------------------------------------------
    ! rocblas_get_device_memory_size
    !---------------------------------------------
    !> \brief
    !> \details
    !> Gets the current device memory size for the handle.
    !> Returns ``rocblas_status_invalid_handle`` if ``handle`` is nullptr,
    !> ``rocblas_status_invalid_pointer`` if ``size`` is nullptr, and ``rocblas_status_success``
    !> otherwise.
    !> @param[in]
    !> handle          rocblas handle
    !> @param[out]
    !> size            current device memory size for the handle
    function rocblas_get_device_memory_size(handle, size) &
       result(get_device_memory_size) &
       bind(C, name="rocblas_get_device_memory_size")
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
       type(c_ptr), value :: size
       integer(c_int) :: get_device_memory_size
    end function rocblas_get_device_memory_size

    !---------------------------------------------
    ! rocblas_set_device_memory_size
    !---------------------------------------------
    !> \brief
    !> \details
    !> Changes the size of allocated device memory at runtime.
    !>
    !> Any previously allocated device memory managed by the handle is freed.
    !>
    !> If size > 0 sets the device memory size to the specified size (in bytes).
    !> If size == 0, frees the memory allocated so far, and lets rocBLAS manage device memory in the
    !> future, expanding it when necessary.
    !> Returns rocblas_status_invalid_handle if handle is nullptr; rocblas_status_invalid_pointer if
    !> size is nullptr; rocblas_status_success otherwise
    !> @param[in]
    !> handle          rocblas handle
    !> @param[in]
    !> size            size of allocated device memory
    function rocblas_set_device_memory_size(handle, size) &
       result(set_device_memory_size) &
       bind(C, name="rocblas_set_device_memory_size")
       import :: c_ptr, c_long, c_int
       type(c_ptr), value :: handle
       integer(c_long), value :: size
       integer(c_int) :: set_device_memory_size
    end function rocblas_set_device_memory_size

    !---------------------------------------------
    ! rocblas_set_workspace
    !---------------------------------------------
    !> \brief
    !> \details
    !> Sets the device workspace for the handle to use.
    !>
    !> Any previously allocated device memory managed by the handle is freed.
    !>
    !> Returns ``rocblas_status_invalid_handle`` if ``handle`` is nullptr and
    !> ``rocblas_status_success`` otherwise.
    !> @param[in]
    !> handle          rocblas handle
    !> @param[in]
    !> addr            address of workspace memory
    !> @param[in]
    !> size            size of workspace memory
    function rocblas_set_workspace(handle, addr, size) &
       result(set_workspace) &
       bind(C, name="rocblas_set_workspace")
       import :: c_ptr, c_long, c_int
       type(c_ptr), value :: handle
       type(c_ptr), value :: addr
       integer(c_long), value :: size
       integer(c_int) :: set_workspace
    end function rocblas_set_workspace

